from scipy.optimize import least_squares
def model(p,t,P):
    A,k,b0,b1,b2,m=p
    return -A*(1-np.exp(-k*t)) + (b0+b1*P+b2*P**2)*(1-np.exp(-m*t))
def res(p): return model(p,t,P)-dP_dt
best=None
for k0 in [0.3,1,2]:
  for m0 in [0.3,1]:
    r=least_squares(res,[7,k0,0,-1,0.2,m0])
    if best is None or r.cost<best.cost: best=r
print(best.x, np.mean(best.fun**2)/np.var(dP_dt))

